void process_widget_ptr(std::shared_ptr<int> sp) { /* ... */ }
void process_gadget_ptr(std::unique_ptr<int> up) { /* ... */ }
void process_raw_ptr(char* p) { /* ... */ }

template<typename Func, typename PtrT>
void forward_ptr(Func f, PtrT p) {
    f(p); // Forward the pointer-like argument
}

// In some function body:
forward_ptr(process_widget_ptr, 0);       // ERROR: Deduces PtrT=int, can't pass int to shared_ptr
forward_ptr(process_gadget_ptr, NULL);    // ERROR: Deduces PtrT=long, can't pass long to unique_ptr
forward_ptr(process_raw_ptr, nullptr);  // OK: Deduces PtrT=std::nullptr_t, which converts to char*
